(() => {
  if (new URLSearchParams(location.search).get('edit') !== '1') return;
  const key='laraib-placement-v1';
  const targets={heading:'.inside-heading',room:'#room-frame',tulips:'.study-tulips',helper:'.smiski-dock',navigation:'.room-directory',resumeButton:'.room-directory a[href="#resume"]',projectsButton:'.room-directory a[href="#projects"]',educationButton:'.room-directory a[href="#education"]',contactButton:'.room-directory a[href="#contact"]',credits:'.trinket-credits'};
  const labels={heading:'Study heading',room:'Whole room panel',tulips:'Tulips',helper:'Smiski question bar',navigation:'All navigation buttons',resumeButton:'Résumé button',projectsButton:'Projects button',educationButton:'Education button',contactButton:'Contact button',credits:'Photo credits'};
  let data={phone:{page:{},scene:{}},desktop:{page:{},scene:{}}},profile=innerWidth<768?'phone':'desktop',selected='page:room',enabled=true,drag=null,history=[],lockSelection=false;
  const clean=value=>{const out={phone:{page:{},scene:{}},desktop:{page:{},scene:{}}};for(const mode of ['phone','desktop'])for(const kind of ['page','scene'])for(const [id,v] of Object.entries(value?.[mode]?.[kind]||{})){if(!/^[a-zA-Z]+$/.test(id)||!Array.isArray(v)||v.length!==(kind==='page'?2:3)||!v.every(n=>Number.isFinite(n)&&Math.abs(n)<=100))continue;out[mode][kind][id]=v;}return out;};
  try{data=clean(JSON.parse(localStorage.getItem(key)||'{}'));}catch{}
  const panel=document.createElement('aside');panel.id='placement-panel';panel.setAttribute('aria-label','Local layout editor');panel.innerHTML=`<details open><summary>✦ Placement mode</summary><p>Drag things into place. Saved only in this browser.</p><label>Layout <select id="placement-profile"><option value="phone">Phone placements</option><option value="desktop">Desktop placements</option></select></label><label>Selected item <select id="placement-item"></select></label><label><input id="placement-enabled" type="checkbox" checked> Dragging enabled</label><p class="placement-hint">Click an item to select it, then drag. Arrow keys nudge; Shift moves faster. For 3D objects, dragging moves across the camera view.</p><div><button id="placement-undo">Undo</button><button id="placement-reset">Reset item</button><button id="placement-reset-all">Reset layout</button></div><div><button id="placement-export">Export placements</button><label class="placement-file">Import JSON<input id="placement-import" type="file" accept="application/json"></label></div><button id="placement-exit">Exit editor</button><output id="placement-status" aria-live="polite"></output><p class="placement-hint">Export the file and share it here when you want these placements published. Phone/desktop presets are independent; use your browser’s responsive viewport to preview each size.</p></details>`;document.body.append(panel);if(innerWidth<768)panel.querySelector('details').open=false;
  const $=id=>panel.querySelector('#'+id),status=$('placement-status');
  function save(){try{localStorage.setItem(key,JSON.stringify(data));status.textContent=`Saved ${profile} placements locally.`;}catch{status.textContent='Browser storage unavailable. Export to keep your edits.';}}
  function remember(){history.push(JSON.stringify(data));if(history.length>40)history.shift();}
  function apply(){for(const [id,selector] of Object.entries(targets)){const el=document.querySelector(selector);if(!el)continue;const v=data[profile].page[id]||[0,0];el.style.translate=v[0]+'vw '+v[1]+'vh';}for(const id of window.studyPlacement?.list()||[])window.studyPlacement.set(id,data[profile].scene[id]||[0,0,0]);highlight();}
  function highlight(){document.querySelectorAll('.placement-selected').forEach(e=>e.classList.remove('placement-selected'));const [kind,id]=selected.split(':');if(enabled&&kind==='page')document.querySelector(targets[id])?.classList.add('placement-selected');status.textContent=(kind==='scene'?'3D object: ':'Page item: ')+(labels[id]||id);}
  function options(){const picker=$('placement-item');picker.replaceChildren();for(const [id,label] of Object.entries(labels)){const option=new Option(label,'page:'+id);picker.add(option);}for(const id of window.studyPlacement?.list()||[])picker.add(new Option('3D · '+id,'scene:'+id));picker.value=selected;}
  function choose(value,lock=false){lockSelection=lock;selected=value;$('placement-item').value=value;highlight();}
  function move(dx,dy){const [kind,id]=selected.split(':');if(kind==='scene'){const v=window.studyPlacement?.move(id,dx,dy);if(v)data[profile].scene[id]=v;}else{const v=data[profile].page[id]||[0,0];data[profile].page[id]=[v[0]+dx/innerWidth*100,v[1]+dy/innerHeight*100];const el=document.querySelector(targets[id]);if(el)el.style.translate=data[profile].page[id].map((n,i)=>n+(i?'vh':'vw')).join(' ');}}
  $('placement-profile').value=profile;$('placement-profile').onchange=e=>{profile=e.target.value;history=[];apply();};
  $('placement-item').onchange=e=>choose(e.target.value,true);
  $('placement-enabled').onchange=e=>{enabled=e.target.checked;document.body.classList.toggle('placement-mode',enabled);highlight();};
  $('placement-undo').onclick=()=>{if(history.length){data=clean(JSON.parse(history.pop()));apply();save();}};
  $('placement-reset').onclick=()=>{remember();const [kind,id]=selected.split(':');delete data[profile][kind][id];apply();save();};
  $('placement-reset-all').onclick=()=>{remember();data[profile]={page:{},scene:{}};apply();save();};
  $('placement-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='laraib-study-placements.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  $('placement-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50000)throw Error();const value=JSON.parse(await file.text());if(!value.phone&&!value.desktop)throw Error();remember();data=clean(value);apply();save();}catch{status.textContent='Could not import that placement file.';}e.target.value='';};
  $('placement-exit').onclick=()=>{const url=new URL(location.href);url.searchParams.delete('edit');location.href=url.href;};
  document.addEventListener('pointerdown',e=>{if(!enabled||panel.contains(e.target)||e.button!==0)return;let value=null;if(e.target.id==='room-canvas'&&!lockSelection){const id=window.studyPlacement?.pick(e.clientX,e.clientY);if(id)value='scene:'+id;}if(!value){const [kind,id]=selected.split(':');if(lockSelection&&(kind==='scene'&&e.target.id==='room-canvas'||kind==='page'&&document.querySelector(targets[id])?.contains(e.target)))value=selected;else for(const [id,selector] of Object.entries(targets).reverse())if(e.target.closest(selector)){value='page:'+id;break;}}if(!value)return;e.preventDefault();e.stopImmediatePropagation();choose(value,lockSelection);remember();drag={x:e.clientX,y:e.clientY,id:e.pointerId};},true);
  document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;e.preventDefault();e.stopImmediatePropagation();move(e.clientX-drag.x,e.clientY-drag.y);drag.x=e.clientX;drag.y=e.clientY;},true);
  for(const name of ['pointerup','pointercancel'])document.addEventListener(name,e=>{if(!drag)return;e.preventDefault();e.stopImmediatePropagation();drag=null;save();},true);
  document.addEventListener('click',e=>{if(enabled&&!panel.contains(e.target)&&e.target.closest('#inside-view')){e.preventDefault();e.stopImmediatePropagation();}},true);
  document.addEventListener('keydown',e=>{if(!enabled||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();remember();const step=e.shiftKey?10:1;move(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0);save();},true);
  window.addEventListener('blur',()=>{if(drag){drag=null;save();}});
  window.addEventListener('study-placement-ready',()=>{options();apply();});
  window.addEventListener('resize',()=>{if(drag)return;const next=innerWidth<768?'phone':'desktop';if(next!==profile){profile=next;$('placement-profile').value=profile;history=[];apply();}});
  document.body.classList.add('placement-mode');options();apply();if(!location.hash||location.hash==='#outside')location.hash='inside';
})();
